			function onDti6ValueChange(e){
				var dti6 = e.control;
				
				if (dti6.value == "") {
				    return;
				}
				
			    var now = new Date();
			    var y = now.getFullYear();
			    var m = now.getMonth() + 1;
			    var d = now.getDate();
			    
			    var date = y + "" + (m < 10 ? "0" + m : m) + "" + (d < 10 ? "0" + d : d);
			    
			    //console.log("date", date);
			    //console.log("dti6.value", dti6.value);
			    
			    if (Number(dti6.value) > Number(date)) {
			        
			        util.Msg.alert(app, "생일은 과거 일자여야 합니다.");
			        
			        dti6.value = "";
			        
			    } else {
			        
			    	var dmMemberInfo = app.lookup("dmMemberInfo");
			    	
			    	if (dmMemberInfo.getValue("YNGBGS_PRTCR_SE_CD") == "Y") {
			    		
			    		var dmFullFourteen = app.lookup("dmFullFourteen");
			    		
			    		//console.log("fullFourteen", dmFullFourteen.getValue("fullFourteen"));
			    		//console.log("dti6", dti6.value);
			    		
			    		if (dti6.value < dmFullFourteen.getValue("fullFourteen")) {  // 만 14세 이상
			    			util.Control.setVisible(app, false, ["grp59"]);
			    		    util.Control.setVisible(app, true, ["grp53"]);
			    		    dmMemberInfo.setValue("STTY_AGT_NM", "");
			                dmMemberInfo.setValue("STTY_AGT_CTTPC_TELNO", "");
			                fullFourteen = true;
			    		} else {  // 만 14세 미만
			    			util.Control.setVisible(app, false, ["grp53"]);
			    		    util.Control.setVisible(app, true, ["grp59"]);
			    		    dmMemberInfo.setValue("RGN_CD", "");
			                dmMemberInfo.setValue("WRD_TELNO", "");
			                dmMemberInfo.setValue("MBL_TELNO", "");
			                fullFourteen = false;
			    		}
			    	}
				}
			}

