			function onIpb53Blur(e){
				//var ipb53 = e.control;
				
				var ipb53 = app.lookup("ipb53");  // 사용자 아이디
			    
			    if (ipb53.readOnly != true && !ValueUtil.isNull(ipb53.value)) {
				    
				    var testStr = ipb53.value.replace(/[0-9]/g, "");
				    
				    if (!/^[a-z0-9]+$/i.test(ipb53.value)) {
				        util.Msg.alert(app, "아이디는 알파벳과 숫자로만 구성됩니다.");
				        ipb53.value = "";
				        
				    } else if (testStr.length == 0) {
				        util.Msg.alert(app, "아이디는 알파벳을 포함해야 합니다.");
				        ipb53.value = "";
				        
				    } else if (ipb53.value.length < 6 || ipb53.value.length > 30) {
				        util.Msg.alert(app, "아이디 길이는 6자 이상 30자 이하입니다.");
				        ipb53.value = "";
				    }
			    }
			    
			}

