			function onIpb50Keyup(e){
				var ipb50 = e.control;
				if (ipb50.displayText != null && ipb50.displayText.trim() != "") {
			        ipb50.value = util.Validator.phoneFormatter(ipb50.displayText, 1);
			    }
			}

			/*
			 * "인증번호 받기" 버튼(btn9)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtn9Click(e){
			    var btn9 = e.control;
			    
			    var dmMemberInfo = app.lookup("dmMemberInfo");
			    var sttyAgtCttpcTelno = dmMemberInfo.getValue("STTY_AGT_CTTPC_TELNO");
			    
			    if (sttyAgtCttpcTelno == null || sttyAgtCttpcTelno == "") {
			        util.Msg.alert(app, "보호자 휴대폰 번호를 입력해주시기 바랍니다.");
			        return;
			    }
			    
			    if (!util.Validator.isTelMobile(sttyAgtCttpcTelno)) {
			        util.Msg.alert(app, "휴대폰 번호 양식을 확인해주시기 바랍니다.");
			        return;
			    }
			    
			    var dmAuthSms = app.lookup("dmAuthSms");
			    dmAuthSms.setValue("STTY_AGT_CTTPC_TELNO", sttyAgtCttpcTelno);
			    
			    util.Submit.send(app, "subAuthSms", function(pbSuccess) {
			    	if (pbSuccess) {
			    		util.Msg.alert(app, "인증번호가 전송되었습니다.");
			    		var dmResult = app.lookup("dmResult");
			    		dmResult.setValue("RESULT", "0");
			    		util.Control.redraw(app, ["ipb39"]);
			    	}
			    });
			}

